INSERT INTO `case_studies` VALUES
('1', 'fintech-saas-funnel-resuscitation', 'Scaling B2B Acquisition: 240% Demo Booking Growth for PayGuard', 'PayGuard Technologies', 'Enterprise FinTech SaaS', 'Enterprise FinTech SaaS', 'Web Development & Performance Marketing', 'Web Development & Performance Marketing', 'PayGuard was burning $85,000 monthly across Google Ads and LinkedIn without generating qualified enterprise demos. Their website was slow, messaging was unclear, and 88% of inbound traffic dropped off before completing the demo form.', '$840 CAC / 1.1% Demo Conv', '$290 CAC / 4.6% Demo Conv', 'Qualified Pipeline Growth', 'PayGuard was burning $85,000 monthly across Google Ads and LinkedIn without generating qualified enterprise demos. Their website was slow, messaging was unclear, and 88% of inbound traffic dropped off before completing the demo form.', 'BusinessDoctor redesigned and rebuilt the core web application using custom PHP/HTML5, built an interactive product demo widget, and restructured their Google Search and LinkedIn paid media campaigns around high-intent keywords.', 'BusinessDoctor redesigned and rebuilt the core web application using custom PHP/HTML5, built an interactive product demo widget, and restructured their Google Search and LinkedIn paid media campaigns around high-intent keywords.', NULL, 'Within 90 days, demo booking conversions climbed by 318% while customer acquisition costs fell by 65%. Annual Recurring Revenue (ARR) grew by $3.4M in two quarters.', 'Within 90 days, demo booking conversions climbed by 318% while customer acquisition costs fell by 65%. Annual Recurring Revenue (ARR) grew by $3.4M in two quarters.', 'uploads/cases/fintech-saas-funnel-architecture-cover.svg', 'FinTech payment pipeline and conversion telemetry architectural schematic (Placeholder)', '[\"uploads\\/cases\\/fintech-payment-pipeline-diagram.svg\"]', 'BusinessDoctor solved what three previous agencies couldn\'t. Having software engineers and performance marketers working on the exact same project was a game changer.', 'Marcus Vance', 'Chief Revenue Officer, PayGuard Technologies', 'Scaling B2B Acquisition: 240% Demo Booking Growth for PayGuard', 'PayGuard was burning $85,000 monthly across Google Ads and LinkedIn without generating qualified enterprise demos. Their website was slow, messaging was unclear', 'published', '1', '1', '2026-11-02 06:00:33', '2026-11-02 06:00:33', '2026-11-02 06:00:33', NULL, '0'),
('2', 'd2c-apparel-vital-infrastructure-overhaul', 'Custom E-Commerce Architecture: Sub-Second Load & 162% Revenue Surge for AURA Atelier', 'AURA Atelier', 'Luxury D2C & Apparel', 'Luxury D2C & Apparel', 'Web Development & UI/UX Design', 'Web Development & UI/UX Design', 'AURA Atelier suffered heavy cart abandonment on mobile devices due to an outdated, plugin-heavy theme with 4.8-second load times and broken mobile layouts.', '4.8s Page Load / 1.4% Conv', '0.68s Page Load / 3.9% Conv', 'Net Conversion Surge', 'AURA Atelier suffered heavy cart abandonment on mobile devices due to an outdated, plugin-heavy theme with 4.8-second load times and broken mobile layouts.', 'We engineered a bespoke, lightweight PHP/HTML5 storefront with dynamic image compression, instant AJAX cart transitions, and a streamlined 1-page checkout flow.', 'We engineered a bespoke, lightweight PHP/HTML5 storefront with dynamic image compression, instant AJAX cart transitions, and a streamlined 1-page checkout flow.', NULL, 'Mobile page load dropped to 680 milliseconds. Mobile checkout abandonment declined by 52%, resulting in an immediate $1.85M revenue lift within 60 days of launch.', 'Mobile page load dropped to 680 milliseconds. Mobile checkout abandonment declined by 52%, resulting in an immediate $1.85M revenue lift within 60 days of launch.', 'uploads/cases/d2c-ecommerce-edge-infrastructure-cover.svg', 'High-volume D2C e-commerce edge infrastructure and flash-sale concurrency diagram (Placeholder)', '[\"uploads\\/cases\\/d2c-inventory-routing-topology.svg\"]', 'The technical speed and clean UI transformed our business. Our store feels instantaneous, and sales have increased dramatically.', 'Elena Rostova', 'Founder & Creative Director, AURA Atelier', 'Custom E-Commerce Architecture: Sub-Second Load & 162% Revenue Surge for AURA Atelier', 'AURA Atelier suffered heavy cart abandonment on mobile devices due to an outdated, plugin-heavy theme with 4.8-second load times and broken mobile layouts.', 'published', '1', '2', '2026-11-02 06:00:33', '2026-11-02 06:00:33', '2026-11-02 06:00:33', NULL, '0'),
('3', 'multichannel-retail-marketplace-dominance', 'Marketplace Management & ROAS Scaling: 4.6x Ad Return for Apex Industrial', 'Apex Industrial', 'Industrial Equipment & B2B Retail', 'Industrial Equipment & B2B Retail', 'E-Commerce & Marketplace Management', 'E-Commerce & Marketplace Management', 'Apex Industrial was losing Buy Box share on Amazon and Flipkart due to unauthorized resellers, poor product titles, and unoptimized ad campaigns.', '1.8x ROAS / 34% Buy Box Loss', '4.6x ROAS / 94% Buy Box Control', 'Marketplace Revenue Scale', 'Apex Industrial was losing Buy Box share on Amazon and Flipkart due to unauthorized resellers, poor product titles, and unoptimized ad campaigns.', 'BusinessDoctor implemented Brand Registry brand gating, redesigned catalog listings with rich A+ lifestyle modules, and restructured Sponsored Brands and Sponsored Products campaigns.', 'BusinessDoctor implemented Brand Registry brand gating, redesigned catalog listings with rich A+ lifestyle modules, and restructured Sponsored Brands and Sponsored Products campaigns.', NULL, 'Buy Box possession stabilized at 94%. Blended advertising return climbed from 1.8x to 4.6x while net marketplace operating profit margin expanded by 11.2 percentage points.', 'Buy Box possession stabilized at 94%. Blended advertising return climbed from 1.8x to 4.6x while net marketplace operating profit margin expanded by 11.2 percentage points.', 'uploads/cases/multichannel-marketplace-hub-cover.svg', 'Omnichannel marketplace catalog synchronization and automated repricing engine schematic (Placeholder)', '[\"uploads\\/cases\\/omnichannel-catalog-sync-architecture.svg\"]', 'BusinessDoctor gave us total command over Amazon and Flipkart. Our listings look world-class, and our ad spend is driving high-margin volume.', 'David Thorne', 'VP of Omnichannel Sales, Apex Industrial', 'Marketplace Management & ROAS Scaling: 4.6x Ad Return for Apex Industrial', 'Apex Industrial was losing Buy Box share on Amazon and Flipkart due to unauthorized resellers, poor product titles, and unoptimized ad campaigns.', 'published', '1', '3', '2026-11-02 06:00:33', '2026-11-02 06:00:33', '2026-11-02 06:00:33', NULL, '0');

