  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(191) NOT NULL,
  `category` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `reading_time` varchar(50) NOT NULL DEFAULT '6 min read',
  `summary` text NOT NULL,
  `excerpt` text DEFAULT NULL,
  `content` longtext NOT NULL,
  `featured_image` varchar(255) DEFAULT NULL,
  `cover_image_alt` varchar(255) DEFAULT NULL,
  `author_name` varchar(150) NOT NULL,
  `author` varchar(150) DEFAULT NULL,
  `author_title` varchar(150) NOT NULL DEFAULT 'Senior Consultant',
  `author_bio` text DEFAULT NULL,
  `tags` varchar(255) DEFAULT NULL,
  `seo_title` varchar(255) DEFAULT NULL,
  `seo_description` text DEFAULT NULL,
  `canonical_url` varchar(255) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `schema_mode` varchar(50) NOT NULL DEFAULT 'auto',
  `custom_schema_json` longtext DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'published',
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  `published_at` datetime DEFAULT current_timestamp(),
