DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(191) NOT NULL,
  `number` varchar(10) NOT NULL,
  `name` varchar(255) NOT NULL,
  `short_title` varchar(150) NOT NULL,
  `tagline` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `deliverables` longtext DEFAULT NULL,
  `kpis` longtext DEFAULT NULL,
  `icon` text DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `sort_order` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_services_slug` (`slug`),
  KEY `idx_services_active_sort` (`is_active`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `services` VALUES
('1', 'web-software-development', '01', 'Web & Custom Software Development', 'Web & Software Dev', 'High-Performance Web Platforms & Enterprise Applications', 'Custom enterprise websites, fast web applications, client portals, and secure database solutions engineered with modern PHP, HTML5, and clean JavaScript.', 'We engineer robust, lightning-fast web and software applications tailored to your business operations. From high-converting business websites to scalable SaaS platforms, internal portals, and custom database web tools, our engineering delivers sub-second load times, ironclad security, and seamless user experiences.', '[\"Custom Corporate & Business Websites\",\"Web Application & Client Portal Development\",\"E-Commerce & Multi-Vendor Storefronts\",\"Database Architecture & API Integrations\",\"Speed Optimization & Core Web Vitals (95+ score)\"]', '[\"< 0.8s Global Load Times\",\"100% Mobile Responsive\",\"Zero Framework Bloat\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\" ry=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"/></svg>', '1', '1', '2026-11-10 05:39:22', '2026-11-10 05:39:22'),
('2', 'digital-marketing-seo', '02', 'Digital Marketing & Performance Ads', 'Digital Marketing & SEO', 'Search Engine Dominance, Google Ads & Paid Media Scaling', 'Comprehensive SEO, high-ROI Google Ads campaigns, social media marketing, and data-backed lead generation strategies that drive qualified customer acquisition.', 'Accelerate your revenue with targeted digital marketing. We develop data-driven campaigns across Google Search, Meta Ads, LinkedIn B2B, and high-intent organic search channels—focusing on customer acquisition cost (CAC) reduction, conversion rates, and measurable return on ad spend (ROAS).', '[\"Search Engine Optimization (Technical, On-Page & Local SEO)\",\"Google Search, Display & Performance Max Ads (PPC)\",\"Social Media Marketing & Paid Social Campaigns (Meta & LinkedIn)\",\"Conversion Funnel Optimization & Lead Generation\",\"Advanced Web Analytics & Conversion Tracking Setup\"]', '[\"3.8x Average Campaign ROAS\",\"+160% Organic Search Traffic\",\"Audited Zero Ad Waste\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m4.93 4.93 4.24 4.24\"/><path d=\"m14.83 9.17 4.24-4.24\"/><path d=\"m14.83 14.83 4.24 4.24\"/><path d=\"m9.17 14.83-4.24 4.24\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/></svg>', '1', '2', '2026-11-10 05:39:22', '2026-11-10 05:39:22'),
('3', 'ui-ux-branding', '03', 'UI/UX Design & Brand Identity', 'UI/UX & Branding', 'Human-Centered Digital Interfaces & Distinct Visual Branding', 'Modern UI/UX design, interactive prototypes, corporate logo design, brand style guides, and digital marketing creatives that make your brand stand out.', 'First impressions define customer trust. Our design division crafts intuitive user interfaces (UI) and frictionless user experiences (UX) paired with distinctive brand identity systems. We help companies elevate their market authority, command premium pricing, and convert visitors into loyal clients.', '[\"Comprehensive UI\\/UX Design & Wireframing\",\"Corporate Brand Identity & Logo Systems\",\"Design Systems & Interactive Component Libraries\",\"Marketing Collateral, Pitch Decks & Brochures\",\"Conversion-Focused Landing Page Designs\"]', '[\"Flawless User Journeys\",\"Modern Design Tokens\",\"High Trust & Engagement\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 2 7 12 12 22 7 12 2\"/><polyline points=\"2 17 12 22 22 17\"/><polyline points=\"2 12 12 17 22 12\"/></svg>', '1', '3', '2026-11-10 05:39:22', '2026-11-10 05:39:22'),
('4', 'ecommerce-marketplaces', '04', 'E-Commerce & Marketplace Management', 'E-Commerce & Marketplaces', 'Amazon, Flipkart & Multi-Channel Storefront Growth', 'Full-lifecycle e-commerce growth: Amazon and Flipkart account management, A+ content, catalog SEO, Buy Box protection, and marketplace advertising.', 'Maximize your sales on the world’s biggest online marketplaces. We manage complete operations across Amazon, Flipkart, and custom e-commerce stores: optimizing product titles, crafting high-converting A+ lifestyle imagery, managing sponsored ads, and defending your brand from unauthorized sellers.', '[\"Full Amazon & Flipkart Seller Account Management\",\"Product Listing Optimization & Catalog SEO\",\"A+ Content Modules & Brand Storefront Design\",\"Marketplace Advertising (Sponsored Products & Brands)\",\"Buy Box Strategy & Brand Registry Protection\"]', '[\"95%+ Buy Box Possession\",\"4.2x Marketplace ROAS\",\"Top Search Visibility\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"9\" cy=\"21\" r=\"1\"/><circle cx=\"20\" cy=\"21\" r=\"1\"/><path d=\"M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6\"/></svg>', '1', '4', '2026-11-10 05:39:22', '2026-11-10 05:39:22'),
('5', 'creative-video-production', '05', 'Creative Production & Video Marketing', 'Creative & Video', 'Studio Product Photography, Video Production & Social Creatives', 'High-resolution commercial product photography, brand promo videos, engaging Reels and Shorts, and motion graphics that captivate digital audiences.', 'High-quality visuals are essential for digital conversions. Our creative team produces professional studio product photos, corporate video shoots, engaging short-form social video (Reels, Shorts, TikTok), and 3D product animations tailored for digital ad performance and social media growth.', '[\"Commercial & Studio Product Photography\",\"Corporate Brand Video & Company Storytelling\",\"Short-Form Video Production (Reels, TikTok, YouTube Shorts)\",\"Product Demo Videos & Motion Graphic Walkthroughs\",\"Ad Creatives & Performance Video Editing\"]', '[\"4K Ultra HD Quality\",\"+220% Social Engagement\",\"High-Converting Creatives\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"23 7 16 12 23 17 23 7\"/><rect x=\"1\" y=\"5\" width=\"15\" height=\"14\" rx=\"2\" ry=\"2\"/></svg>', '1', '5', '2026-11-10 05:39:22', '2026-11-10 05:39:22'),
('6', 'cloud-it-consulting', '06', 'Cloud Solutions & IT Consulting', 'Cloud & IT Consulting', 'Cloud Infrastructure, DevOps, Cybersecurity & Systems Maintenance', 'Strategic IT consulting, cloud server setup, continuous website maintenance, security audits, and business process automation.', 'Ensure your digital assets remain fast, secure, and always accessible. We provide enterprise-level IT consulting, cloud infrastructure management (AWS, Google Cloud, DigitalOcean), ongoing website maintenance, vulnerability patching, backup automation, and digital transformation consulting.', '[\"Cloud Architecture & Server Deployment\",\"Website Maintenance, Uptime & Performance Monitoring\",\"Cybersecurity Audits, SSL & Vulnerability Patching\",\"Business Workflow & CRM Automation\",\"Strategic Digital Transformation Consulting\"]', '[\"99.9% Uptime Guarantee\",\"24\\/7 Monitoring & Backups\",\"Zero Security Breaches\"]', '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg>', '1', '6', '2026-11-10 05:39:22', '2026-11-10 05:39:22');

